import{_ as o,q as s,o as i,c as r,m as a,j as h,y as l,b as e}from"./chunks/framework.D3-xQjZb.js";const d="/images/teaching/studio-coach-pause.jpg",b=JSON.parse('{"title":"Teaching AI","description":"Keith Williams shares his Studio method at NJIT, a guide for faculty and engineering mentors designing AI-assisted assignments people can test and explain.","frontmatter":{"title":"Teaching AI","description":"Keith Williams shares his Studio method at NJIT, a guide for faculty and engineering mentors designing AI-assisted assignments people can test and explain.","teaser":"In my NJIT Studios, I decide what the AI coach can handle and which decision a learner needs to own. The distinction matters to anyone who mentors engineers."},"headers":[],"relativePath":"teaching.md","filePath":"teaching.md"}'),u={name:"teaching.md"};function c(p,t,g,m,y,f){const n=s("ReaderTable");return i(),r("div",null,[t[1]||(t[1]=a('<h1 id="teaching-ai" tabindex="-1">Teaching AI <a class="header-anchor" href="#teaching-ai" aria-label="Permalink to &quot;Teaching AI&quot;">​</a></h1><p>I teach web development, web applications, and content management at NJIT, and I direct the undergraduate Enterprise AI program. Across those settings, I design assignments around a handoff. A classmate tries to buy a T-shirt. A reviewer asks what an automated check actually checked. Watching the person who built the work respond tells me something a finished screen cannot.</p><p>If you teach a course or mentor a new engineer, pick one decision you want to watch the learner make. In the Studios below, it might be choosing a buyer, calling the winner of a game, or finding out why a website is unreachable. If you’re here for your IS373 project, <a href="/knowledge-lab/students/" target="_self">open the student guide</a> to choose your next step.</p><h2 id="what-could-you-learn-if-you-could-listen-to-every-student-work" tabindex="-1">What Could You Learn If You Could Listen to Every Student Work? <a class="header-anchor" href="#what-could-you-learn-if-you-could-listen-to-every-student-work" aria-label="Permalink to &quot;What Could You Learn If You Could Listen to Every Student Work?&quot;">​</a></h2><p>Take an assignment you already teach. Where would you like to sit beside a student and ask what they’re thinking? The Studio template lets you put that question into the assignment. During grading, AI can help you find the evidence for one student’s feedback and compare responses across the class to decide what to revisit. <a href="/teaching/when-ai-helps-write-the-code">Read the classroom feature</a></p><p><img src="'+d+'" alt="A learner holds a pencil over a blank card beside a worked example."></p><h2 id="build-something-you-can-explain" tabindex="-1">Build something you can explain <a class="header-anchor" href="#build-something-you-can-explain" aria-label="Permalink to &quot;Build something you can explain&quot;">​</a></h2><p>I call these activities <em>Studios</em>. Students try a starter, choose one change, build it with help, and check what actually happened. A plain-text file called <code>AGENTS.md</code> tells the AI assistant when to help, what to ask, and when to wait. Open a starter below to see what that looks like in practice.</p>',8)),h(n,{label:"Table: Build something you can explain"},{default:l(()=>[...t[0]||(t[0]=[e("table",null,[e("thead",null,[e("tr",null,[e("th",null,"Studio"),e("th",null,"A decision the student makes")])]),e("tbody",null,[e("tr",null,[e("td",null,[e("a",{href:"https://github.com/kaw393939/is117-brand-studio",target:"_blank",rel:"noreferrer"},"Brand Studio · Intro to Website Development")]),e("td",null,"Choose the audience for a plain white T-shirt. Point to one design or wording choice that fits that buyer.")]),e("tr",null,[e("td",null,[e("a",{href:"https://github.com/kaw393939/is218-rps-starter",target:"_blank",rel:"noreferrer"},"Rock, Paper, Scissors · Building Web Applications")]),e("td",null,"Predict the outcome of a round from the player’s point of view. Check a test, then play it yourself.")]),e("tr",null,[e("td",null,[e("a",{href:"https://github.com/kaw393939/373_hosting",target:"_blank",rel:"noreferrer"},"Server Studio · Content Management Systems")]),e("td",null,"Predict how a request will reach a calculator running on your server. Open the public address and see what happens.")])])],-1)])]),_:1}),t[2]||(t[2]=a('<p>In the <a href="/knowledge-lab/" target="_self">Knowledge Lab</a>, I use a club handbook to give students two different decisions. Can they find who organizes events? What should the app say about a meeting room the handbook never names? <a href="/knowledge-lab/students/check" target="_self">Use those two questions to check a RAG app</a>.</p><h2 id="try-a-studio-in-your-course" tabindex="-1">Try a Studio in your course <a class="header-anchor" href="#try-a-studio-in-your-course" aria-label="Permalink to &quot;Try a Studio in your course&quot;">​</a></h2><p>Pick an assignment you already teach and a decision you want students to make. Rehearse the assignment once, playing a student who is stuck. Does the coach give a helpful hint, or does it make the decision for you?</p><p>The download includes a worked example, a student handout, and the coach’s instructions. <strong>The teacher copy contains answers. Share only <code>LESSON.md</code> and <code>AGENTS.md</code> with students.</strong> <a href="/downloads/AI-Studio-Starter.zip">Download the teacher Studio starter</a> · <a href="/teaching/studio-field-notes">Read the research behind the starter</a></p><h2 id="learning-beyond-one-assignment" tabindex="-1">Learning beyond one assignment <a class="header-anchor" href="#learning-beyond-one-assignment" aria-label="Permalink to &quot;Learning beyond one assignment&quot;">​</a></h2><p>The follow-up I care about is what happens on a fresh task, after the coach stops prompting. I describe the comparison I’d like to study in my <a href="/research">research agenda</a>. The <a href="/ai-careers">AI career field guide</a> connects classroom practice to responsibilities employers assign to engineers.</p><p>If you want to try a Studio in another course, send me the task and the decision you want the learner to own. I’d like to hear what they choose when you hand them the keyboard. <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Contact me through NJIT</a></p><p>I also publish two tools for colleagues building their own materials. The Educational Design System provides reusable layouts for course sites. Everyday AI CLI is an alpha command-line toolkit for repeatable AI tasks. <a href="https://kaw393939.github.io/educational-design-system/" target="_blank" rel="noreferrer">Explore the Educational Design System</a> · <a href="https://github.com/kaw393939/everyday-ai-cli" target="_blank" rel="noreferrer">See Everyday AI CLI</a></p>',8))])}const k=o(u,[["render",c]]);export{b as __pageData,k as default};
